        'test list' = @(@{ n = '--filter'; h = 'only tests whose name contains this text, or that have this tag' }, @{ n = '--tag'; h = 'only tests with this tag' }, @{ n = '--json'; h = 'write machine-readable JSON to stdout' }, @{ n = '-j'; h = 'write machine-readable JSON to stdout' }, @{ n = '--help'; h = 'display this list of options' }, @{ n = '-h'; h = 'display this list of options' })
        'completion' = @(@{ n = '--json'; h = 'write machine-readable JSON to stdout' }, @{ n = '-j'; h = 'write machine-readable JSON to stdout' }, @{ n = '--help'; h = 'display this list of options' }, @{ n = '-h'; h = 'display this list of options' })
    }
    # The value an option takes (node|option): path, dir, text, choice <values>, dyn.
    $values = @{
        'convert|--format' = 'choice bim tmdl pbip'
        'convert|-f' = 'choice bim tmdl pbip'
