        'deploy|1' = 'text'
        'deploy|2' = 'text'
        'data init|0' = 'path'
        'data init|1' = 'dir'
        'data check|0' = 'path'
        'data check|1' = 'dir'
        'data info|0' = 'path'
        'data info|1' = 'dir'
        'data embed|0' = 'path'
        'data embed|1' = 'dir'
        'data embed|2' = 'path'
        'refresh|0' = 'path'
        'refresh|*' = 'dyn'
        'test run|0' = 'path'
        'test run|*' = 'path'
        'test init|0' = 'path'
        'test snapshot|0' = 'path'
